            { "white.browse.filter", new[]{ "程序或快捷方式|*.exe;*.lnk|程序|*.exe|快捷方式|*.lnk", "Programs or shortcuts|*.exe;*.lnk|Programs|*.exe|Shortcuts|*.lnk" } },
            { "white.pick.title", new[]{ "选运行中的程序", "Pick a running program" } },
            { "white.pick.sub", new[]{ "仅列出当前用户启动且带窗口的程序，不含系统进程和反作弊。", "Lists only windowed programs started by the current user; system processes and anti-cheat are excluded." } },
