            { "set.about", new[]{ "Pavise {0} {1} 本地配置与用户白名单", "Pavise {0} {1} local settings and user whitelist" } },

            { "set.hags", new[]{ "GPU 硬件加速调度 HAGS", "GPU hardware-accelerated scheduling HAGS" } },
            { "set.hags.n", new[]{ "将显存分配与任务排期交由显卡自身的调度器管理，减少一层中转。近年对照测试中，它对平均帧率的影响基本落在误差范围内，不应作为提帧项使用。其真正意义在于作为前置条件：RTX 40/50 系的驱动级帧生成与 NVIDIA Smooth Motion 等功能要求其处于开启状态，关闭时不可用。需要使用帧生成时应开启；不使用时两种状态均可，仍建议自行开关对比一局。重启后生效。", "Hands VRAM allocation and task scheduling to the GPU's own scheduler, removing one layer of indirection. In recent controlled tests its effect on average frame rate falls within the margin of error, so it should not be treated as a frame-rate booster. Its real significance is as a prerequisite: driver-side frame generation on RTX 40/50 series and features such as NVIDIA Smooth Motion require it to be on and are unavailable while it is off. Enable it if you need frame generation; otherwise either state is acceptable, and comparing one match each way is still advised. Takes effect after a reboot." } },
            { "hags.reboot", new[]{ "已写入 HAGS 设置，重启电脑后生效。", "HAGS setting written; takes effect after restarting the PC." } },
            { "vbs.blocked.policy", new[]{ "VBS 由组策略或 MDM 策略强制开启，本机改动会被策略刷新覆盖。请先在管理端解除强制，再来关闭。", "VBS is enforced by Group Policy or MDM; local changes would be overwritten on the next policy refresh. Remove the enforcement on the management side first, then disable it here." } },
            { "vbs.blocked.lock", new[]{ "VBS 或内存完整性带 UEFI 锁，关闭需要在开机时物理确认，注册表与启动项改动不会生效。Pavise 不做这项改动，避免状态永远停留在等待重启。", "VBS or memory integrity has a UEFI lock; disabling it requires physical confirmation at boot, and registry/boot changes will not take effect. Pavise skips this change so the state never gets stuck at pending-reboot." } },
            { "hags.unsupported", new[]{ "本机 GPU 或驱动不支持硬件加速 GPU 调度，需要 WDDM 2.7 及以上版本的驱动。", "This GPU or driver does not support hardware-accelerated GPU scheduling; a WDDM 2.7 or newer driver is required." } },
            { "set.vbs", new[]{ "关闭虚拟化安全 VBS", "Disable virtualization-based security VBS" } },
            { "vbs.state.on", new[]{ "VBS 已开启。关闭会降低系统安全性，帧数变化因机器而异，请自行对比。", "VBS is on. Disabling it lowers system security; frame rate changes vary by machine — compare for yourself." } },
            { "vbs.state.off", new[]{ "VBS 未运行，本机已无此项开销。", "VBS is not running; this machine no longer carries this overhead." } },
            { "vbs.state.pending", new[]{ "已设为关闭，重启电脑后生效。", "Set to disabled; takes effect after restarting the PC." } },
            { "vbs.state.unknown", new[]{ "状态未知，无法通过 WMI 查询。", "State unknown; could not query via WMI." } },
            { "vbs.warn", new[]{ "关闭 VBS 与内存完整性，并停用虚拟化底层\r\n\r\n系统安全性将下降，WSL2、Docker、Hyper-V 和 Windows 沙盒将无法使用。帧数提升因机器而异，请自行前后对比。\r\n\r\n重启后生效，后续恢复同样需要重启一次。", "Disable VBS and memory integrity, and turn off the virtualization layer\r\n\r\nSystem security will decrease, and WSL2, Docker, Hyper-V and Windows Sandbox will stop working. The frame rate gain varies by machine — compare before and after yourself.\r\n\r\nTakes effect after a reboot; restoring later also requires one reboot." } },
            { "vbs.needadmin", new[]{ "修改 VBS 和 hypervisor 需要管理员权限，请以管理员身份运行 Pavise。", "Changing VBS and the hypervisor requires administrator rights. Please run Pavise as administrator." } },
            { "vbs.done", new[]{ "已关闭 VBS 并停用 hypervisor\r\n重启电脑后生效。重启后 WSL2、Docker、Hyper-V 和 Windows 沙盒将无法使用。需要恢复请回到此处关闭该开关后重启。", "VBS disabled and hypervisor turned off\r\nTakes effect after restarting the PC. After the reboot, WSL2, Docker, Hyper-V and Windows Sandbox will be unavailable. To restore, come back here, turn this switch off, then reboot." } },
            { "vbs.restored", new[]{ "已恢复 VBS，hypervisor 启动类型已改回原值\r\n重启电脑后生效，之后 WSL2、Docker 等恢复可用。", "VBS restored; the hypervisor launch type has been set back to its original value\r\nTakes effect after restarting the PC, after which WSL2, Docker and the rest work again." } },
            { "vbs.restorefail", new[]{ "还原未完全成功，bcdedit 可能执行失败。原状态快照已保留，可重试一次，详见日志。", "Restore did not fully succeed; bcdedit may have failed. The original-state snapshot is preserved — you can retry once. See the log for details." } },

            { "set.specmit", new[]{ "卸载推测执行缓解", "Unload speculative-execution mitigations" } },
            { "spec.blocked.query", new[]{ "无法通过内核接口读取当前缓解状态。Pavise 不做无法核对的写入，因此不执行本项。", "The current mitigation state cannot be read through the kernel interface. Pavise does not make writes it cannot verify, so this option is skipped." } },
            { "spec.blocked.hardwarefixed", new[]{ "本机 CPU 的推测执行漏洞已在硬件层修复，没有软件缓解在运行。关闭它只会降低安全性，换不来任何帧数。", "This CPU fixes the speculative-execution vulnerabilities in hardware and runs no software mitigation. Disabling it would only lower security without gaining any frames." } },
            { "spec.state.on", new[]{ "以下软件缓解正在运行，每次内核态往返都要付它们的固定开销：", "The following software mitigations are running and charge a fixed cost on every kernel transition: " } },
            { "spec.state.off", new[]{ "本机没有软件缓解在运行，已无此项开销。越新的处理器越可能落在这一档。", "No software mitigation is running on this machine; this overhead is already absent. Newer processors are more likely to land here." } },
            { "spec.state.pending", new[]{ "已设为关闭，重启电脑后生效。重启后回到此处即可看到缓解是否真的已停止。", "Set to disabled; takes effect after restarting the PC. Come back here after the reboot to see whether the mitigations actually stopped." } },
            { "spec.state.unknown", new[]{ "状态未知，内核接口查询失败。", "State unknown; the kernel query failed." } },
            { "spec.warn", new[]{ "关闭 Spectre 与 Meltdown 的软件缓解\r\n\r\n系统对这两类推测执行漏洞的防护将被移除。利用它们需要攻击者先能在本机执行代码，但风险确实存在，请自行判断。\r\n\r\n收益随处理器年龄递增，六到八代酷睿最明显，十代之后接近于零。帧数变化请自行前后对比。\r\n\r\n重启后生效，后续恢复同样需要重启一次。", "Disable the software mitigations for Spectre and Meltdown\r\n\r\nProtection against these two classes of speculative-execution vulnerability will be removed. Exploiting them requires an attacker to already run code on this machine, but the risk is real — judge for yourself.\r\n\r\nThe gain grows with processor age: largest on 6th-8th gen Core, near zero after 10th gen. Compare frame rates before and after yourself.\r\n\r\nTakes effect after a reboot; restoring later also requires one reboot." } },
            { "spec.done", new[]{ "已写入关闭设置\r\n缓解位由内核在启动时读取，重启电脑后生效。重启后可回到此处核对缓解是否真的已停止。需要恢复请关闭该开关后重启。", "The disable setting has been written\r\nThe kernel reads these bits at boot, so it takes effect after restarting the PC. After the reboot you can return here to verify the mitigations actually stopped. To restore, turn this switch off and reboot." } },
            { "spec.restored", new[]{ "已恢复推测执行缓解\r\n重启电脑后生效。", "Speculative-execution mitigations restored\r\nTakes effect after restarting the PC." } },
            { "spec.restorefail", new[]{ "还原未完全成功。原值快照已保留，可重试一次，详见日志。", "Restore did not fully succeed. The original-value snapshot is preserved — you can retry once. See the log for details." } },

            { "log.idlestate.1", new[]{ "对局禁用处理器空闲 已开启 下一次写入托管方案时生效", "Disable processor idle: enabled; takes effect the next time the managed plan is written" } },
            { "log.idlestate.2", new[]{ "对局禁用处理器空闲 已关闭 托管方案写回允许空闲", "Disable processor idle: turned off; the managed plan is written back to allow idle" } },
            { "log.specmitigation.1", new[]{ "推测执行缓解 注册表写入失败 已回滚 ", "Speculative-execution mitigations: registry write failed, rolled back " } },
            { "log.specmitigation.2", new[]{ "推测执行缓解 状态标记写入失败 已回滚 ", "Speculative-execution mitigations: state marker write failed, rolled back " } },
            { "log.specmitigation.3", new[]{ "推测执行缓解 已写入关闭设置 缓解位由内核在启动时读取 重启后生效 ", "Speculative-execution mitigations: disable setting written. The kernel reads these bits at boot, so it takes effect after a restart " } },
            { "log.specmitigation.4", new[]{ "推测执行缓解 检测到虚拟化安全正在运行 部分缓解由虚拟机监控程序托管 不随本项一并解除 ", "Speculative-execution mitigations: virtualization-based security is running; some mitigations are managed by the hypervisor and are not lifted by this option " } },
            { "log.specmitigation.5", new[]{ "推测执行缓解 关闭异常 ", "Speculative-execution mitigations: disable failed " } },
            { "log.specmitigation.6", new[]{ "推测执行缓解 还原失败 原值快照保留 ", "Speculative-execution mitigations: restore failed; original-value snapshot preserved " } },
            { "log.specmitigation.7", new[]{ "推测执行缓解 状态标记清除失败 ", "Speculative-execution mitigations: state marker could not be cleared " } },
            { "log.specmitigation.8", new[]{ "推测执行缓解 已还原 重启后生效 ", "Speculative-execution mitigations restored; takes effect after a restart " } },
