            { "log.panelformsettingspage.12", new[]{ " 未确认完成", " not confirmed complete" } },
            { "set.lang", new[]{ "界面语言", "Language" } },
            { "set.lang.n", new[]{ "选择语言后立即生效 界面与新产生的日志提示一并切换", "Select a language to apply it immediately; the UI and newly written log messages switch together." } },
            { "lang.zh", new[]{ "中文", "中文" } },
            { "lang.en", new[]{ "English", "English" } },
        };

        public static void Init()
        {
            Cur = Settings.LoadStr("Lang", "zh") == "en" ? 1 : 0;
        }

        public static void Set(int i)
        {
            Cur = i == 1 ? 1 : 0;
            Settings.SaveStr("Lang", Cur == 1 ? "en" : "zh");
        }

#if PAVISE_SELFTEST
        internal static List<string> AllKeys()
        {
            var keys = new List<string>();
            foreach (var kv in M) keys.Add(kv.Key);
            return keys;
        }

        internal static string[] Row(string key)
        {
            string[] a;
            return M.TryGetValue(key, out a) ? a : null;
        }
#endif

        public static string T(string key)
        {
            string[] a;
            if (M.TryGetValue(key, out a)) return a[Cur < a.Length ? Cur : 0];
            return key;
        }

        public static string F(string key, params object[] args) { return string.Format(T(key), args); }

        public static bool HasKey(string key) { return key != null && M.ContainsKey(key); }
    }

